  audio=el; xfAudio=oldEl;
  curTrackIdx=ni; curTrack=tr.title; curArtist=tr.artist||''; curSongId=tr.songId; curPf=tr.platform||'wy'; curCover=cov||tr.cover||''; curCandidates=cands; curCandIdx=0; curActualQuality=q; errFor='';
  updateQualityUI(); updateMediaSession(); updateVinyl(); updatePlayer();
  haoRecentAdd({songId:tr.songId, title:tr.title, artist:tr.artist||'', platform:tr.platform||'wy', cover:cov, dur:durOf(tr)||0});
  haoRecordListen({songId:tr.songId, title:tr.title, artist:tr.artist||'', platform:tr.platform||'wy', cover:cov, dur:durOf(tr)||0});
  if(document.getElementById('myRecent')) loadMyRecent();
