async function copyText(s){ try{ await navigator.clipboard.writeText(s); toast(t('copied')); }catch(e){ showAlert(s); } }
// Logout always asks first: a stray tap (e.g. a finger lifting after a
// vertical swipe) must never sign the user out by accident.
// Clear cache (settings, side menu). Asks first, then:
//  - in the App: posts to the native `clearCache` handler, which wipes only
//    WKWebsiteDataStore disk/memory/offline caches (NOT localStorage /
//    cookies, so the login token survives). The native side calls back
//    window.__clearCacheDone() when finished.
//  - in a browser: the native handler does not exist, so the web-side
//    clear runs immediately.
// Web-side clear: Cache Storage (if any) + reload. A 3s fallback timer
// covers a native handler that never calls back.
async function clearCache(){
  const r = await showConfirm({title: t('clearCacheT'), text: t('clearCacheConfirm'), ok: t('clearCacheT'), cancel: t('cancelT') || '取消'});
  if (!r) return;
  let done = false;
  window.__clearCacheDone = function(){ if (done) return; done = true; finishClearCache(); };
  setTimeout(function(){ if (!done) { done = true; finishClearCache(); } }, 3000);
  try {
    const h = window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.clearCache;
    if (h) { h.postMessage({}); return; }
  } catch (e) {}
  // No native handler (plain browser): finish right away.
  if (!done) { done = true; finishClearCache(); }
}
async function finishClearCache(){
  try { if (window.caches && caches.keys) { const keys = await caches.keys(); for (const k of keys) { try { await caches.delete(k); } catch (e) {} } } } catch (e) {}
  toast(t('cacheCleared'));
  setTimeout(function(){ location.reload(); }, 600);
}
