  const res = j.result || {};
  const list = res.playlists || [];
  return { items: list.map(function(x){ return { platform: 'wy', id: String(x.id), name: x.name || '', cover: directCoverHi(x.coverImgUrl || ''), creator: (x.creator && x.creator.nickname) || '', playCount: Number(x.playCount) || 0, trackCount: Number(x.trackCount) || 0, desc: x.description || '' }; }).filter(function(x){ return x.id && x.name; }), total: Number(res.playlistCount) || 0 };
