async function directSearchTXArtists(q, page){
  const per = 30;
  const j = await nativeJson('https://c.y.qq.com/soso/fcgi-bin/search_for_qq_cp?g_tk=5381&uin=0&format=json&inCharset=utf-8&outCharset=utf-8&notice=0&platform=h5&needNewCode=1&w=' + encodeURIComponent(q) + '&zhidaqu=1&catZhida=1&t=0&flag=1&ie=utf-8&sem=1&aggr=0&perpage=' + per + '&n=' + per + '&p=' + page + '&remoteplace=txt.mqq.all', { headers: { Referer: 'https://y.qq.com/', 'User-Agent': DIRECT_MUSIC_UA } }, 10000);
  const d = j.data || {};
  const norm = function(s){ return String(s || '').replace(/[\s\(\)（）\[\]·\-]/g, '').toLowerCase(); };
  const qn = norm(q);
  const items = []; const seen = new Set();
  const pic = function(mid){ return directCoverHi('https://y.gtimg.cn/music/photo_new/T001R300x300M000' + mid + '.jpg'); };
  const add = function(mid, name, musicSize, albumSize){ if (!mid || !name || seen.has(mid)) return; seen.add(mid); items.push({ platform: 'tx', id: mid, name: name, cover: pic(mid), musicSize: Number(musicSize) || 0, albumSize: Number(albumSize) || 0, alias: '' }); };
  const z = d.zhida;
  if (z && z.type === 2 && z.singermid) add(z.singermid, z.singername, z.songnum, z.albumnum);
  const songs = (d.song && d.song.list) || [];
  const counts = {}; const names = {};
  for (const s of songs) for (const sg of (s.singer || [])) {
    if (!sg.mid || !sg.name) continue;
    if (/;|、/.test(sg.name)) continue;
    counts[sg.mid] = (counts[sg.mid] || 0) + 1; names[sg.mid] = sg.name;
  }
  const ranked = Object.keys(counts).sort(function(a, b){ return counts[b] - counts[a]; });
  for (const mid of ranked) {
    const nm = norm(names[mid]);
    if (nm.includes(qn) || qn.includes(nm)) add(mid, names[mid], 0, 0);
  }
  return { items: items, total: items.length };
}
async function directSearchArtists(q, page){
  const p = Math.max(1, Number(page) || 1);
  const settled = await Promise.all([directSearchWYArtists(q, p).catch(function(){ return { items: [], total: 0 }; }), directSearchKWArtists(q, p).catch(function(){ return { items: [], total: 0 }; }), directSearchTXArtists(q, p).catch(function(){ return { items: [], total: 0 }; })]);
  const w = settled[0], k = settled[1], t = settled[2];
  const total = w.total + k.total + t.total;
  const seen = new Set();
  const artists = w.items.concat(t.items, k.items).filter(function(x){ const key = x.platform + '|' + x.id; if (seen.has(key)) return false; seen.add(key); return true; });
  return { ok: true, artists: artists, total: total, hasMore: (p * 30) < total };
}

// ---- singer / album detail, direct (port of server artistDetailWY/TX/KW, albumSongsWY) ----
async function directArtistDetailWY(id){
  const u = 'https://music.163.com/api/v1/artist/songs?id=' + encodeURIComponent(id);
  const hd = { headers: { 'User-Agent': DIRECT_MUSIC_UA } };
  const pair = await Promise.all([
    nativeJson('https://music.163.com/api/artist/albums/' + encodeURIComponent(id) + '?limit=30&offset=0', hd, 15000).catch(function(){ return {}; }),
    nativeJson(u + '&limit=100&offset=0', hd, 15000).catch(function(){ return {}; })
  ]);
  const ar = pair[0], first = pair[1];
  let allSongs = first.songs || [];
  const total = Number(first.total) || 0;
  const pages = Math.min(Math.ceil(total / 100), 10);
  if (pages > 1) {
    const rest = await Promise.all(Array.from({ length: pages - 1 }, function(v, k){ return nativeJson(u + '&limit=100&offset=' + ((k + 1) * 100), hd, 15000).catch(function(){ return { songs: [] }; }); }));
    for (const r of rest) allSongs = allSongs.concat(r.songs || []);
  }
  if (!allSongs.length) {
    try { const sr = await nativeJson('https://music.163.com/api/artist/top/song?id=' + encodeURIComponent(id) + '&limit=100', hd, 15000); allSongs = sr.songs || []; } catch (e) {}
  }
  const songs = allSongs.map(function(s){ return { songId: String(s.id), title: s.name || '', artist: ((s.artists || s.ar) || []).map(function(a){ return a.name; }).join(' / ') || '', platform: 'wy', dur: Math.round(Number((s && s.duration != null ? s.duration : s.dt) || 0) / 1000), cover: directCoverHi(((s.album && s.album.picUrl) || (s.al && s.al.picUrl)) || ''), vipOnly: (s.fee === 1 || s.fee === 4) ? 1 : 0, album: ((s.album && s.album.name) || (s.al && s.al.name)) || '', albumYear: (function(pt){ return pt ? new Date(pt).getFullYear() : 0; })((s.album && s.album.publishTime) || (s.al && s.al.publishTime) || 0) }; });
  const albums = (ar.hotAlbums || []).map(function(a){ return { id: String(a.id), name: a.name || '', cover: directCoverHi(a.picUrl || ''), publishTime: Number(a.publishTime) || 0, songCount: Number(a.size) || 0, artist: (a.artist && a.artist.name) || '' }; });
  const artist = ar.artist || {};
  return { name: artist.name || '', pic: directCoverHi(artist.picUrl || ''), musicSize: Number(artist.musicSize) || 0, albumSize: Number(artist.albumSize) || 0, songs: songs, albums: albums };
}
async function directArtistDetailTX(mid, name){
  const q = String(name || mid || '').trim();
  if (!q) return { name: '', pic: '', musicSize: 0, albumSize: 0, songs: [], albums: [] };
  const jobs = [1, 2, 3].map(function(p){ return nativeJson('https://c.y.qq.com/soso/fcgi-bin/search_for_qq_cp?g_tk=5381&uin=0&format=json&inCharset=utf-8&outCharset=utf-8&notice=0&platform=h5&needNewCode=1&w=' + encodeURIComponent(q) + '&zhidaqu=1&catZhida=1&t=0&flag=1&ie=utf-8&sem=1&aggr=0&perpage=30&n=30&p=' + p + '&remoteplace=txt.mqq.all', { headers: { Referer: 'https://y.qq.com/', 'User-Agent': DIRECT_MUSIC_UA } }, 15000).catch(function(){ return {}; }); });
  const albP = mid ? nativeJson('https://c.y.qq.com/v8/fcg-bin/fcg_v8_singer_album.fcg?singermid=' + encodeURIComponent(mid) + '&order=time&begin=0&num=30&g_tk=5381&loginUin=0&hostUin=0&format=json&inCharset=utf8&outCharset=utf-8&notice=0&platform=yqq.json&needNewCode=0', { headers: { Referer: 'https://y.qq.com/', 'User-Agent': DIRECT_MUSIC_UA } }, 15000).catch(function(){ return {}; }) : Promise.resolve({});
  const results = await Promise.all(jobs);
  const albJ = await albP;
  const albums = ((albJ.data && albJ.data.list) || []).map(function(a){ return { id: String(a.albumMID || ''), name: a.albumName || '', cover: directCoverHi(a.albumMID ? 'https://y.gtimg.cn/music/photo_new/T002R300x300M000' + a.albumMID + '.jpg' : ''), publishTime: Date.parse(a.pubTime || '') || 0, songCount: Number((a.latest_song && a.latest_song.song_count) || 0) || 0, artist: a.singerName || q }; }).filter(function(a){ return a.id && a.name; });
  const seen = new Set(); const songs = []; let songnum = 0, albumnum = 0;
  for (const j of results) {
    const d = j.data || {}; const z = d.zhida;
    if (z && z.type === 2 && (!mid || z.singermid === mid)) { songnum = Number(z.songnum) || songnum; albumnum = Number(z.albumnum) || albumnum; }
    for (const s of ((d.song && d.song.list) || [])) {
      if (!s.songmid || seen.has(s.songmid)) continue;
      const singers = s.singer || [];
      const mine = mid ? singers.some(function(x){ return x.mid === mid; }) : singers.some(function(x){ return x.name === q; });
      if (!mine) continue;
      seen.add(s.songmid);
      songs.push({ songId: s.songmid, title: s.songname || '', artist: singers.map(function(a){ return a.name; }).join(' / ') || '', platform: 'tx', dur: Number(s.interval) || 0, cover: s.albummid ? directCoverHi('https://y.gtimg.cn/music/photo_new/T002R300x300M000' + s.albummid + '.jpg') : '', vipOnly: 0, album: s.albumname || '', albumYear: 0 });
    }
  }
  return { name: q, pic: mid ? directCoverHi('https://y.gtimg.cn/music/photo_new/T001R300x300M000' + mid + '.jpg') : '', musicSize: songnum || songs.length, albumSize: albums.length || albumnum, songs: songs, albums: albums };
}
