const DIRECT_CMT_PAGE = 30;
const __directCmtAltCache = new Map();
const __directCmtPoolCache = new Map();
async function directComments(songId, platform, title, artist, offset){
  const pf = ['wy', 'tx', 'kg', 'kw'].includes(platform) ? platform : 'wy';
  const off = Math.max(0, parseInt(offset || '0', 10) || 0);
  if (!songId && !title) return { ok: true, hot: [], comments: [], latest: [], hasMore: false, total: 0, hotTotal: 0 };
  const fetchFor = function(p, id, o){
    if (!id) return null;
    if (p === 'wy') return directCommentsWY(id, Math.min(100, 60 + o), 0);
    if (p === 'tx') return directCommentsTX(id, Math.min(100, 40 + o), 0);
    if (p === 'kg') return directCommentsKG(id, Math.min(100, 40 + o), 1);
    if (p === 'kw') return directCommentsKW(id, Math.min(100, 40 + o), 1);
    return null;
  };
  const jobs = [];
  const first = fetchFor(pf, songId, off);
  if (first) jobs.push(first);
  try {
    if (title) {
      const ck = pf + '|' + title + '|' + (artist || '');
      let alts = null;
      const hit = __directCmtAltCache.get(ck);
      if (hit && Date.now() - hit.at < 600000) alts = hit.alts;
      if (!alts) {
        const others = ['wy', 'tx', 'kg', 'kw'].filter(function(p){ return p !== pf; });
        const searchFns = { wy: directSearchWY, tx: directSearchTX, kg: directSearchKG, kw: directSearchKW };
        const all = await directRaceNull(Promise.all(others.map(function(p){ return searchFns[p](title, 3).catch(function(){ return []; }); })).then(function(lists){ const a = []; lists.forEach(function(l){ a.push.apply(a, l); }); return a; }), 2500) || [];
        const norm = function(s){ return (s || '').replace(/[\s\(\)（）\[\]·-]/g, '').toLowerCase(); };
        const ta = norm(title), aa = norm((artist || '').split('/')[0]);
        alts = all.filter(function(x){ return x.platform !== pf && norm(x.title) === ta && (!aa || norm((x.artist || '').split('/')[0]) === aa); }).slice(0, 3).map(function(a){ return { platform: a.platform, songId: a.songId }; });
        __directCmtAltCache.set(ck, { at: Date.now(), alts: alts });
        if (__directCmtAltCache.size > 200) { const k0 = __directCmtAltCache.keys().next().value; __directCmtAltCache.delete(k0); }
      }
      for (const a of alts) { const j = fetchFor(a.platform, a.songId, off); if (j) jobs.push(j); }
    }
  } catch (e) {}
  const settled = await Promise.allSettled(jobs);
  const seen = new Set(); let hot = []; const pool = []; let anyOk = false;
  for (const r of settled) { if (r.status !== 'fulfilled' || !r.value || !Array.isArray(r.value.list)) continue; anyOk = true; for (const c of (r.value.hot || [])) { const k = (c.nick || '') + '|' + (c.content || '').slice(0, 60); if (!c.content || seen.has(k)) continue; seen.add(k); hot.push(c); } for (const c of r.value.list) { const k = (c.nick || '') + '|' + (c.content || '').slice(0, 60); if (!c.content || seen.has(k)) continue; seen.add(k); pool.push(c); } }
  if (jobs.length && !anyOk) throw new Error('comments fail');
  hot.sort(function(a, b){ return (b.likes || 0) - (a.likes || 0); });
  const extra = pool.slice().sort(function(a, b){ return (b.likes || 0) - (a.likes || 0); }).filter(function(c){ return (c.likes || 0) > 0; }).slice(0, 5);
  const hotKeys = new Set(extra.map(function(c){ return (c.nick || '') + '|' + (c.content || '').slice(0, 60); }));
  hot = hot.concat(extra).sort(function(a, b){ return (b.likes || 0) - (a.likes || 0); }).slice(0, 15);
  let ordinary = pool.filter(function(c){ return !hotKeys.has((c.nick || '') + '|' + (c.content || '').slice(0, 60)); }).sort(function(a, b){ return (b.time || 0) - (a.time || 0); });
  const pck = pf + '|' + songId + '|' + title + '|' + (artist || '');
  const pcHit = __directCmtPoolCache.get(pck);
  if (pcHit && Date.now() - pcHit.at < 300000) {
    const ck2 = function(c){ return (c.nick || '') + '|' + (c.content || '').slice(0, 60); };
    const have = new Set(pcHit.ordinary.concat(pcHit.hot).map(ck2));
    const add = ordinary.filter(function(c){ return !have.has(ck2(c)); });
    ordinary = pcHit.ordinary.concat(add);
    hot = pcHit.hot;
    __directCmtPoolCache.set(pck, { at: Date.now(), hot: hot, ordinary: ordinary });
  } else {
    __directCmtPoolCache.set(pck, { at: Date.now(), hot: hot, ordinary: ordinary });
    if (__directCmtPoolCache.size > 100) { const k0 = __directCmtPoolCache.keys().next().value; __directCmtPoolCache.delete(k0); }
  }
  const latest = ordinary.slice(off, off + DIRECT_CMT_PAGE);
  return { ok: true, hot: off === 0 ? hot : [], comments: hot.concat(ordinary), latest: latest, hasMore: ordinary.length > off + DIRECT_CMT_PAGE, total: ordinary.length, hotTotal: hot.length };
}
// ---- alt-platform lookup, direct (port of server /api/music/search-public + findAltPlatform) ----
async function directFindAltPlatform(title, artist, excludePf, album){
  const others = ['tx', 'wy', 'kg', 'kw'].filter(function(pf){ return pf !== excludePf; });
  const settled = await Promise.all(others.map(function(pf){ return directSearchOne(pf, title).catch(function(){ return null; }); }));
  const all = [];
  for (const r of settled) if (r && r.ok) all.push.apply(all, r.results || []);
  const order = { tx: 0, wy: 1, kg: 2, kw: 3 };
  all.sort(function(a, b){ return (order[a.platform] == null ? 9 : order[a.platform]) - (order[b.platform] == null ? 9 : order[b.platform]); });
  const norm = function(s){ return (s || '').replace(/[\s\(\)（）\[\]·-]/g, '').toLowerCase(); };
  const ta = norm(title), aa = norm((artist || '').split('/')[0]), al = norm(album || '');
  return all.find(function(x){ return x.platform !== excludePf && norm(x.title) === ta && (!aa || norm((x.artist || '').split('/')[0]) === aa) && (!al || !x.album || norm(x.album) === al); }) || null;
}
// ---- lyrics, direct (port of server lyricWY/lyricTX/parseLrc) ----
function directParseLrc(txt){
  const out = [];
  for (const line of String(txt || '').split('\n')) {
    const m = line.match(/\[(\d+):(\d+(?:\.\d+)?)\]/);
    if (!m) continue;
    const text = line.replace(/\[.*?\]/g, '').trim();
    if (!text || /^(ti|ar|al|by|offset):/i.test(text)) continue;
    if (/^(暂无歌词|纯音乐)/.test(text)) continue;
    out.push({ t: Number(m[1]) * 60 + Number(m[2]), text: text });
  }
  return out.sort(function(a, b){ return a.t - b.t; });
}
