    if (!x.name) continue;
    if (/里番/.test(x.type || '') || /里番/.test(x.name)) continue;
    const k = videoNormTitle(x.name) + '|' + x.year;
    if (seen.has(k)) { const ex = out[seen.get(k)]; const ns = parseFloat(x.score) || 0, os = parseFloat(ex.score) || 0; if (ns > os) ex.score = x.score;
      if (videoNormTitle(x.name) === qp.qn && videoNormTitle(ex.name) !== qp.qn) { const keepScore = ex.score; Object.assign(ex, { id: x.id, pic: x.pic, source: x.source, sourceName: x.sourceName, type: x.type, remarks: x.remarks, total: x.total, area: x.area }); ex.score = keepScore; }
      continue; }
    seen.set(k, out.length);
    out.push(x);
