// Strip a trailing season suffix ("xxx第2季" / "Show Season 2")
// so title lookups use the base series title.
function vodStripSeasonSuffix(title){
  let base=String(title||'').trim();
  if(!base) return {base:base, stripped:false};
  const CN='[0-9０-９]{1,2}|[一二三四五六七八九十百千]+';
  const pats=[
    new RegExp('[\\s\\-–—:：·]*[\\(（]\\s*(?:第(?:'+CN+')季|Season\\s+[0-9]{1,2}(?:\\s+Part\\s+[0-9]{1,2})?|S[0-9]{1,2})\\s*[\\)）]\\s*$','i'),
    new RegExp('第(?:'+CN+')季\\s*$'),
    /\s*Season\s+[0-9]{1,2}(?:\s+Part\s+[0-9]{1,2})?\s*$/i,
    /\s*S[0-9]{1,2}\s*$/i
  ];
  let stripped=false;
  for(let i=0;i<3&&base;i++){
    let changed=false;
    for(const p of pats){
      const nb=base.replace(p,'').trim();
      if(nb!==base){ base=nb; changed=true; stripped=true; break; }
    }
    if(!changed) break;
  }
  if(stripped) base=base.replace(/[\s\-–—:：·.,]+$/,'').trim();
  if(!base) return {base:String(title||'').trim(), stripped:false};
  return {base:base, stripped:stripped};
}
