const DOUBAN_HEADERS = {'User-Agent': DIRECT_MUSIC_UA, 'Referer': 'https://movie.douban.com/'};
const DOUBAN_BUILTIN_IDS = {'流浪地球2':'35267208','庆余年':'25853071','肖申克的救赎':'1292052','霸王别姬':'1291546','泰坦尼克号':'1292722'};
let __doubanChain = Promise.resolve();
let __doubanLastCall = 0;
let __doubanBlockedUntil = 0;
