const DIRECT_ADULT_WORDS = ['伦理','福利','成人','情色','三级','写真','美女','激情','性感'];
function directVideoAdult(x){ return DIRECT_ADULT_WORDS.some(function(w){ return (x.type||'').includes(w) || String(x.name||'').includes(w); }); }
function directVideoItem(s, x){ return { source:s.id, sourceName:s.name, vodId:String(x.vod_id), name:x.vod_name||'', pic:x.vod_pic||'', year:String(x.vod_year||''), type:x.type_name||'', area:x.vod_area||'', score:x.vod_score||'', total:x.vod_total||'', remarks:x.vod_remarks||'', hits:Number(x.vod_hits)||0 }; }
const DIRECT_VIDEO_TYPE_PRIORITY = ['连续剧','电视剧','电影','综艺','动漫','纪录片','动作片','喜剧片','爱情片','科幻片','恐怖片','剧情片','战争片','国产剧','韩剧','欧美剧','日剧','动漫电影','国产动漫','日本动漫','中国动漫','短剧','港剧','台剧','泰剧','港澳剧','台湾剧','古装片','历史片','惊悚片','家庭片','犯罪片','冒险片','动画片'];
const DIRECT_VIDEO_EN_SUB = {'电影':'MOVIES','连续剧':'TV SHOWS','电视剧':'TV SHOWS','综艺':'VARIETY','动漫':'ANIMATION','纪录片':'DOCUMENTARY','动漫电影':'ANIMATED MOVIES','短剧':'SHORT DRAMA','国产剧':'CHINESE DRAMA','韩剧':'K-DRAMA','欧美剧':'WESTERN DRAMA','日剧':'J-DRAMA','港剧':'HK DRAMA','台剧':'TW DRAMA','泰剧':'THAI DRAMA'};
const DIRECT_VIDEO_MOVIE_RE = /电影|纪录|动作片|喜剧片|爱情片|科幻片|恐怖片|剧情片|战争片|古装片|历史片|惊悚片|家庭片|犯罪片|冒险片|动画片|伦理片/;
// Type map (port of server videoTypeMapLoad): type name -> {source, sourceName, typeId}. First source wins. 10-min cache.
let __directVideoTypeMap = null, __directVideoTypeMapAt = 0;
async function directVideoTypeMap(){
  if(__directVideoTypeMap && Date.now()-__directVideoTypeMapAt < 600000) return __directVideoTypeMap;
  const srcs = (await directVideoSources()).filter(function(s){ return s.kind==='play'; });
  const map = new Map();
  await Promise.all(srcs.map(async function(s){
    try{
      const j = await nativeJson(s.apiUrl+'?ac=list', { headers: { 'User-Agent': DIRECT_VIDEO_UA, 'Accept': 'application/json' } }, 8000);
      for(const c of (j.class||[])){
        const nm = String(c.type_name||'').trim();
        if(!nm) continue;
        if(DIRECT_ADULT_WORDS.some(function(w){ return nm.includes(w); }) || nm.includes('里番')) continue;
        if(!map.has(nm)) map.set(nm, {source:s.id, sourceName:s.name, typeId:String(c.type_id)});
      }
    }catch(e){}
  }));
  __directVideoTypeMap = map; __directVideoTypeMapAt = Date.now();
  return map;
}
// Port of server /api/video/daily: 3 workers over play sources, dedup by
// name|year (higher score wins), series first, 12 items. Throws when empty
// so the caller falls back to the server.
async function directVideoDaily(){
  const srcs = (await directVideoSources()).filter(function(s){ return s.kind==='play'; });
  const all = [];
  let di = 0;
  async function worker(){
    while(di < srcs.length){
      const s = srcs[di++];
      try{
        const j = await nativeJson(s.apiUrl+'?ac=videolist&pg=1', { headers: { 'User-Agent': DIRECT_VIDEO_UA, 'Accept': 'application/json' } }, 8000);
        for(const x of (j.list||[])) all.push(directVideoItem(s, x));
      }catch(e){}
    }
  }
  await Promise.all([worker(), worker(), worker()]);
  const seen = new Map();
  const series = [], other = [];
  for(const x of all){
    if(!x.name || !x.pic) continue;
    if(directVideoAdult(x)) continue;
    const k = x.name+'|'+x.year;
    if(seen.has(k)){ const ex=seen.get(k); const ns=parseFloat(x.score)||0, os=parseFloat(ex.score)||0; if(ns>os) ex.score=x.score; continue; }
    seen.set(k,x);
    if((x.type||'').includes('剧')) series.push(x); else other.push(x);
  }
  const items = series.concat(other).slice(0,12);
  if(!items.length) throw new Error('video source unreachable');
  return {ok:true, items:items};
}
// Port of server /api/video/by-type: single source, WIN=10 pages when
// filtered, CMS-side area/year/by params + client-side filter/sort.
async function directVideoByType(name, pg, area, year, by){
  const map = await directVideoTypeMap();
  const m = map.get(name);
  if(!m) throw new Error('type not found');
  const srcs = await directVideoSources();
  const s = srcs.find(function(x){ return String(x.id)===String(m.source); });
  if(!s) throw new Error('source gone');
  const filtered = (area && area!=='all') || (year && year!=='all');
  const WIN = 10;
  const pagesToFetch = filtered ? Array.from({length:WIN}, function(_,i){ return (pg-1)*WIN+1+i; }) : [pg];
  const baseQ = 't='+encodeURIComponent(m.typeId);
  const extraQ = (area&&area!=='all'&&area!=='other'?'&area='+encodeURIComponent(area):'')+(year&&year!=='all'&&year!=='earlier'?'&year='+encodeURIComponent(year):'')+((by==='hits'||by==='score')?'&by='+encodeURIComponent(by):'');
  let anyOk = false;
  const raws = await Promise.all(pagesToFetch.map(async function(p){
    try{
      const j = await nativeJson(s.apiUrl+'?ac=videolist&'+baseQ+'&pg='+p+extraQ, { headers: { 'User-Agent': DIRECT_VIDEO_UA, 'Accept': 'application/json' } }, 8000);
      anyOk = true; return j;
    }catch(e){ return null; }
  }));
  if(!anyOk) throw new Error('video source unreachable');
  let srcPagecount = 1, srcTotal = 0;
  for(const j of raws){ if(j){ srcPagecount=Math.max(srcPagecount, Number(j.pagecount)||1); srcTotal=Math.max(srcTotal, Number(j.total)||0); } }
  let items = [];
  for(const j of raws){ if(!j) continue; for(const x of (j.list||[])){ if(!x.vod_name||!x.vod_pic) continue; items.push(directVideoItem(s, x)); } }
  const AREA_ALIAS = {'大陆':['大陆','中国大陆','内地'],'香港':['香港'],'台湾':['台湾'],'美国':['美国'],'韩国':['韩国'],'日本':['日本'],'英国':['英国']};
  const KNOWN_AREA = ['大陆','中国大陆','内地','香港','台湾','美国','韩国','日本','英国'];
  if(area && area!=='all'){
    if(area==='other'){ items=items.filter(function(x){ return !KNOWN_AREA.some(function(a){ return String(x.area||'').includes(a); }); }); }
    else { const al=AREA_ALIAS[area]||[area]; items=items.filter(function(x){ return al.some(function(a){ return String(x.area||'').includes(a); }); }); }
  }
  if(year && year!=='all'){
    if(year==='earlier'){ items=items.filter(function(x){ const y=parseInt(x.year,10); return !isNaN(y)&&y<=2021; }); }
    else { items=items.filter(function(x){ return String(x.year)===String(year); }); }
  }
  if(by==='hits') items.sort(function(a,b){ return b.hits-a.hits; });
  else if(by==='score') items.sort(function(a,b){ return (parseFloat(b.score)||0)-(parseFloat(a.score)||0); });
  const pagecount = filtered ? Math.max(1, Math.ceil(srcPagecount/WIN)) : srcPagecount;
  return {ok:true, name:name, page:pg, pagecount:pagecount, total:filtered?items.length:srcTotal, items:items};
}
// Port of server buildVideoHome: type rows (batches of 8, 20s deadline),
// sorted by count, top 10 rows; collections + totals.
async function directVideoHome(){
  const map = await directVideoTypeMap();
  const HOME_DEADLINE = Date.now()+20000;
  const names = Array.from(map.keys());
  names.sort(function(a,b){ const ia=DIRECT_VIDEO_TYPE_PRIORITY.indexOf(a), ib=DIRECT_VIDEO_TYPE_PRIORITY.indexOf(b); if(ia>=0&&ib>=0) return ia-ib; if(ia>=0) return -1; if(ib>=0) return 1; return 0; });
  async function homeRowOne(nm){
    const m = map.get(nm);
    const srcs = await directVideoSources();
    const s = srcs.find(function(x){ return String(x.id)===String(m.source); });
    if(!s) return null;
    try{
      const j = await nativeJson(s.apiUrl+'?ac=videolist&t='+encodeURIComponent(m.typeId)+'&pg=1', { headers: { 'User-Agent': DIRECT_VIDEO_UA, 'Accept': 'application/json' } }, 15000);
      const items = (j.list||[]).filter(function(x){ return x.vod_name&&x.vod_pic&&!directVideoAdult({type:x.type_name, name:x.vod_name}); }).map(function(x){ return directVideoItem(s, x); });
      return {name:nm, count:Number(j.total)||items.length, items:items.slice(0,10)};
    }catch(e){ return null; }
  }
  const got = [];
  for(let bi=0; bi<names.length && got.length<12; bi+=8){
    if(Date.now()>HOME_DEADLINE) break;
    const rs = await Promise.race([Promise.all(names.slice(bi,bi+8).map(function(nm){ return homeRowOne(nm); })), new Promise(function(r){ setTimeout(function(){ r([]); }, Math.max(100, HOME_DEADLINE-Date.now())); })]);
    for(const r of rs){ if(r&&r.items.length) got.push(r); }
  }
  got.sort(function(a,b){ return b.count-a.count; });
  const rows = got.slice(0,10);
  const collections = rows.slice(0,5).map(function(r){ return {name:r.name, en:DIRECT_VIDEO_EN_SUB[r.name]||'MEDIA', count:r.count, pics:r.items.slice(0,4).map(function(x){ return x.pic; }), picAlts:r.items.slice(0,4).map(function(x){ return x.picAlt||''; })}; });
  let totMovies = 0, totShows = 0;
  for(const r of rows){ if(DIRECT_VIDEO_MOVIE_RE.test(r.name)) totMovies+=r.count; else totShows+=r.count; }
  const seenEp = new Set(); let totEps = 0;
  for(const r of rows) for(const x of r.items){ const k=x.source+'|'+x.vodId; if(seenEp.has(k)) continue; seenEp.add(k); const n=parseInt(x.total,10); if(!isNaN(n)&&n>0) totEps+=n; }
  if(!rows.length) throw new Error('video source unreachable');
  return {ok:true, collections:collections, rows:rows.map(function(r){ return {name:r.name, count:r.count, items:r.items}; }), totals:{movies:totMovies, shows:totShows, episodes:totEps}};
}
