function prefetchNext(){ if(!playerPlaylist.length||curTrackIdx<0) return; let n; if(playMode==='shuffle'&&playerPlaylist.length>1){ do{ n=Math.floor(Math.random()*playerPlaylist.length);}while(n===curTrackIdx); } else n=(curTrackIdx+1)%playerPlaylist.length; const tr=playerPlaylist[n]; if(!tr) return; nextPrefetchIdx=n; const key=tr.songId+'|'+(tr.platform||'wy')+'|'+curQuality; if(nextUrlCache.key===key&&nextUrlCache.url) return; getPlayUrl(tr.songId,tr.platform||'wy',curQuality,tr.title||'',tr.cover||'').then(r=>{ if(r&&r.url) nextUrlCache={key:key,url:r.url,candidates:(r.candidates&&r.candidates.length?r.candidates:[r.url]),quality:r.quality||curQuality,cover:r.cover||tr.cover||'',via:r.via||''}; }).catch(()=>{}); }
async function playTrack(songId,title,platform,cover,artist,vip,auto,dur,fromIdx){ xfCancel(); xfNativeSent=false; xfAvgRms=0; xfSamples=0; const g=++playGen; queueCleared=false;
  if(haoIsDisliked(title,artist)){ if(__dislikeSkips>=(playerPlaylist.length||1)){ __dislikeSkips=0; toast(t('dislikeAllSkippedT')); return; } __dislikeSkips++; toast(t('dislikeSkippedT')); nextTrack(); return; } __dislikeSkips=0; const prevId=curSongId, prevPf=curPf; const pf=['wy','tx','kg','kw','mg'].includes(platform)?platform:'wy'; if(!auto) altDepth=0; curPf=pf; curTrack=title; curArtist=artist||''; curSongId=songId; curPf=pf; curCover=cover||''; updateVinyl(); loadLyrics(songId,pf,title,artist); const ck=songId+'|'+pf+'|'+curQuality; const r=(nextUrlCache.key===ck&&nextUrlCache.url)?{url:nextUrlCache.url,candidates:nextUrlCache.candidates,quality:nextUrlCache.quality,cover:nextUrlCache.cover,via:nextUrlCache.via||''}:await getPlayUrl(songId,pf,curQuality,title,cover); if(r&&r.via) curResolverKey=r.via;
 if(g!==playGen) return; if(nextUrlCache.key===ck) nextUrlCache={key:'',url:'',candidates:[],quality:'',cover:''}; if(!r.url){ if(altDepth<1){ const alt=await findAltPlatform(title,artist,pf,(playerPlaylist[curTrackIdx]||{}).album||''); if(alt){ altDepth++; playTrack(alt.songId,alt.title,alt.platform,alt.cover,alt.artist,alt.vipOnly,true,alt.dur||0); return; } } playFailed(); return;} curCover=r.cover||cover||''; curActualQuality=r.quality||curQuality; updateQualityUI(); if(r.quality&&r.quality!==curQuality) toast(t('qFallback')); updateMediaSession(); curCandidates=(r.candidates&&r.candidates.length?r.candidates:[r.url]); curCandIdx=0; errFor=''; updateVinyl(); let dur0=Number(dur)||0; if(!dur0){ const m=playerPlaylist.find(t=>String(t.songId)===String(songId)&&(t.platform||'wy')===pf); if(m) dur0=durOf(m); } haoRecentAdd({songId:songId,title:title,artist:artist||'',platform:pf,cover:r.cover||cover||'',dur:dur0}); haoRecordListen({songId:songId,title:title,artist:artist||'',platform:pf,cover:r.cover||cover||'',dur:dur0}); if(document.getElementById('myRecent')) loadMyRecent(); if(String(songId)===String(prevId)&&pf===prevPf&&audio.currentTime>5&&audio.duration&&audio.currentTime<audio.duration-10){ restorePos=audio.currentTime; } else if(!(String(songId)===String(prevId)&&pf===prevPf)){ restorePos=0; } wantPlaying=true; applyVolume(); if(tryNativeMusicPlay(curCandidates[0])){ playing=true; updateVinyl(); updatePlayer(); } else { audio.src=curCandidates[0]; audio.play().then(()=>{ playing=true; updateVinyl(); updatePlayer();}).catch(()=>{ playing=false; updateVinyl(); updatePlayer();}); } haoWakeLockAcquire(); prefetchNext(); postNowPlaying();}
function updateVinyl(){ const v=document.getElementById('vinyl'); if(v) v.classList.toggle('playing',playing); const sh=document.getElementById('playerSheet'); if(sh) sh.classList.toggle('playing',playing); const songChanged=String(curSongId||'')!==String(__lastVinylSongId||''); const cv=document.getElementById('vinylCover'); const sc=document.getElementById('sheetCover'); if(songChanged&&sc&&curCover){ if(__coverSlideTimer){ clearTimeout(__coverSlideTimer); __coverSlideTimer=null; } const pn=document.getElementById('playerNow'); const oldClip=pn?pn.querySelector('.sheet-cover-clip'):null; if(oldClip) oldClip.remove(); if(pn){ const wrap=document.createElement('div'); wrap.className='sheet-cover-clip'; try{ wrap.style.borderRadius=getComputedStyle(sc).borderRadius||'16px'; }catch(e){} const nx=document.createElement('img'); nx.className='sheet-cover-next'; nx.src=curCover; nx.onerror=function(){ this.src='./music-cover.svg'; }; const dir=__slideDir>=0?1:-1; nx.style.transform='translateX('+(dir*100)+'%)'; wrap.appendChild(nx); (document.getElementById('plCoverBox')||pn).appendChild(wrap); void nx.offsetWidth; nx.style.transition='transform .3s ease'; nx.style.transform='translateX(0)'; __coverSlideTimer=setTimeout(()=>{ __coverSlideTimer=null; if(sc) sc.src=curCover||'./music-cover.svg'; if(wrap.parentNode) wrap.parentNode.removeChild(wrap); },320); } else if(sc) sc.src=curCover||'./music-cover.svg'; } else if(sc) sc.src=curCover||'./music-cover.svg'; if(cv && curCover){ cv.src=curCover; if(songChanged){ cv.classList.remove('mini-cover-fade'); void cv.offsetWidth; cv.classList.add('mini-cover-fade'); } } [cv,sc].forEach(function(im){ if(im&&!im._pfb){ im._pfb=1; im.addEventListener('error',function(){ const s=im.getAttribute('src')||''; if(s.indexOf('music-cover.svg')<0) im.src='./music-cover.svg'; }); } }); const bg=document.getElementById('sheetBg'); if(bg) bg.style.backgroundImage=curCover?('url('+curCover+')'):''; const mt=document.getElementById('miniTitle'); if(mt) mt.textContent=curTrack||'♪ 黑胶 · 点我播放'; const ma=document.getElementById('miniArtist'); if(ma) ma.textContent=curArtist||''; const mp=document.getElementById('miniPlay'); if(mp) mp.innerHTML=ic(playing?'pause':'play'); updatePlayer(); updateMediaSession(); syncMiniPlayer(); if(songChanged){ __lastVinylSongId=String(curSongId||''); const dirCls=__slideDir>=0?'song-slide-next':'song-slide-prev'; __slideDir=1; const tm=document.querySelector('.sheet-title-meta'); const mm=document.querySelector('.mini-meta'); [tm,mm].forEach(function(el){ if(!el) return; el.classList.remove('song-slide-next','song-slide-prev'); void el.offsetWidth; el.classList.add(dirCls); setTimeout(()=>{ el.classList.remove('song-slide-next','song-slide-prev'); },340); }); } }

// ===== WIDGET: report current track to the native app =====
let __lastNowPlayingKey='';
function postNowPlaying(){
  if(!(window.__HAO_NATIVE__ && window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.nativePlayer)) return;
  if(!curTrack) return;
  const key=curTrack+'|'+curArtist+'|'+(playing?'1':'0')+'|'+(wantPlaying?'1':'0');
  if(key===__lastNowPlayingKey) return;
  __lastNowPlayingKey=key;
  try{ window.webkit.messageHandlers.nativePlayer.postMessage({kind:'nowPlaying', title:curTrack||'', artist:curArtist||'', cover:curCover||'', songId:String(curSongId||''), playing:!!playing, wantPlaying:!!wantPlaying, position:(audio&&audio.currentTime)||0, duration:(audio&&audio.duration)||0}); }catch(e){}
}
// CarPlay bridge: the native CarPlay scene reads the queue / user
// playlists through these helpers (called via callAsyncJavaScript).
// They return JSON strings; missing data -> empty lists, never throws.
window.__carplayQueue = async function(){ try{ if(!playerPlaylist.length) await loadPlayerPlaylist(); return JSON.stringify({tracks:playerPlaylist.map(function(t){ return {songId:t.songId,title:t.title,artist:t.artist,platform:t.platform||'wy',cover:t.cover||''}; })}); }catch(e){ return JSON.stringify({tracks:[]}); } };
window.__carplayLists = function(){ return JSON.stringify({lists:haoListsGet().map(function(l){ return {id:l.id,name:l.name,count:(l.tracks||[]).length,cover:((l.tracks||[])[0]||{}).cover||''}; })}); };
window.__carplayListSongs = function(listId){ const l=haoListsGet().find(function(x){ return String(x.id)===String(listId); }); return JSON.stringify({tracks:((l&&l.tracks)||[]).map(function(t){ return {songId:t.songId,title:t.title,artist:t.artist,platform:t.platform||'wy',cover:t.cover||''}; })}); };
window.__carplayPlay = async function(kind, listId, idx){ try{ if(kind==='list'){ curListId=String(listId||''); localStorage.setItem('curListId',curListId); await loadPlayerPlaylist(); } else { if(!playerPlaylist.length) await loadPlayerPlaylist(); } playTrackAt(idx||0); return true; }catch(e){ return false; } };
function togglePlay(){ if(!curTrack){ const f=playerPlaylist[0]; if(f) playTrack(f.songId,f.title,f.platform||'wy',f.cover,f.artist,f.vipOnly); return;} if(nativeMusicOn){ const toPlay=!playing; wantPlaying=toPlay; playing=toPlay; try{ window.webkit.messageHandlers.nativeMusic.postMessage({kind: toPlay?'resume':'pause'}); }catch(e){} updateVinyl(); return; } if(useNativeMusic()&&!playing){ const tr=playerPlaylist[curTrackIdx]; if(tr){ playTrack(tr.songId,tr.title,tr.platform||'wy',tr.cover,tr.artist,tr.vipOnly); return; } } if(playing){wantPlaying=false; clearWebAutoResume(); audio.pause();playing=false;}else{wantPlaying=true;audio.play();playing=true;} updateVinyl(); }
function setLang(v){ lang=v; localStorage.setItem('lang',v); if(typeof syncMenu==='function') syncMenu(); applyPrefs(); render(); load(); }
function setMode(m){ if(m!=='system'&&m!=='day'&&m!=='night') return; mode=m; try{ localStorage.setItem('mode',m); }catch(e){} applyPrefs(); render(); syncMenu(); }
function toggleMode(){ setMode(mode==='system'?'day':(mode==='day'?'night':'system')); }
function modeToggleHTML(){ if(mode==='system') return ic('sun')+' '+t('day'); if(mode==='day') return ic('moon')+' '+t('night'); return t('modeSystemT'); }
function goPage(h){ closeMenu(); location.hash=h; }
