// L02: per-room follow status — each followed room is checked directly
// (its own play-info/detail call) instead of trusting hot-list page 1,
// so follows outside page 1 are no longer mis-marked offline.
// directLiveRoomStatus returns {online, viewers, title, startedAt,
// failed}; failed=true means the CHECK could not run (network/timeout
// or no native bridge) — not offline. Callers show an unknown badge
// and count it for retry instead of greying the card.
let liveFollowStatusFailCount=0;
async function directLiveRoomStatus(platform, roomId, gameId){
  if (platform==='bili'){
    // Bilibili: live_status straight from getRoomPlayInfo — a clean
    // online/offline signal, plus live_start_time for alert dedup.
    try{
      const j=await nativeJson('https://api.live.bilibili.com/xlive/web-room/v2/index/getRoomPlayInfo?room_id='+encodeURIComponent(roomId)+'&protocol=0,1&format=0,1,2&codec=0,1&qn=250&platform=web&ptype=8', {headers:{'User-Agent': DIRECT_LIVE_UA, 'Referer': 'https://live.bilibili.com/'+encodeURIComponent(roomId)}}, 12000);
      const ri=(j&&j.data&&j.data.room_info)||{};
      return {online:Number(ri.live_status)===1, viewers:directLiveNum(ri.online), title:ri.title||'', startedAt:Number(ri.live_start_time)||0, failed:false};
    }catch(e){ return {online:false, viewers:0, title:'', startedAt:0, failed:true}; }
  }
  // Other platforms: resolve the room's own play URL. A room with a
  // playable URL is live; a clean "no stream" answer is offline. Only
  // a transport failure counts as failed.
  try{
    const d=await directLivePlayApi(platform, roomId, gameId);
    if (d&&d.ok&&d.url) return {online:true, viewers:directLiveNum(d.online||d.viewers), title:d.title||'', startedAt:0, failed:false};
    const err=(d&&d.error)||'';
    if (err==='direct play empty'||err.indexOf('douyu play failed')===0||err.indexOf('not found')>=0||err.indexOf('may have ended')>=0) return {online:false, viewers:0, title:'', startedAt:0, failed:false};
    return {online:false, viewers:0, title:'', startedAt:0, failed:true};
  }catch(e){ const m=String((e&&e.message)||e||''); const off=m.indexOf('douyu play failed')>=0||m.indexOf('huya play failed')>=0||m.indexOf('direct play empty')>=0||m.indexOf('not found')>=0||m.indexOf('may have ended')>=0; return {online:false, viewers:0, title:'', startedAt:0, failed:!off}; }
}
// Shared follow-status fetch used by haoRefreshFollowStatus and
// showLiveFollows. Hot page 1 is fetched ONCE per platform as a fast
// path (a member there is live, no per-room call needed); every other
// follow gets its own directLiveRoomStatus check.
async function haoFetchFollowStatusMap(items){
  const smap={}; let failCount=0;
  const byPlat={};
  for (const f of items){ (byPlat[f.platform]=byPlat[f.platform]||[]).push(f); }
  for (const p of Object.keys(byPlat)){
    let hot=null;
    try{ hot=await directLiveRooms(p, {parent:'', cat:'', page:1}); }catch(e){ hot=null; }
    const hotMap={};
    (hot||[]).forEach(function(r){ hotMap[String(r.roomId)]=r; });
    for (const f of byPlat[p]){
      const key=p+':'+f.roomId;
      const hit=hotMap[String(f.roomId)];
      if (hit){ smap[key]={platform:p, roomId:f.roomId, online:true, viewers:hit.online||hit.viewers||0, title:hit.title||f.title||'', startedAt:0, failed:false}; continue; }
      let gid='';
      try{ gid=f.gameId||(JSON.parse(f.meta||'{}').gameId)||''; }catch(e){ gid=f.gameId||''; }
      const st=await directLiveRoomStatus(p, f.roomId, gid);
      if (st.failed) failCount++;
      smap[key]={platform:p, roomId:f.roomId, online:!!st.online, viewers:st.viewers||0, title:st.title||f.title||'', startedAt:st.startedAt||0, failed:!!st.failed};
    }
  }
  return {smap:smap, failCount:failCount};
}
async function haoRefreshFollowStatus(){ const items=haoLiveFollowsGet(); if(!items.length) return; try{ const r=await haoFetchFollowStatusMap(items); liveFollowStatusMap=r.smap; liveFollowStatusErr=r.failCount>0; liveFollowStatusFailCount=r.failCount; if(liveFollowsShowing){ const list=document.getElementById('liveList'); if(list) renderLiveFollowsList(list, liveFollowItems.length?liveFollowItems:items, r.smap); } }catch(e){} }
