function haoLiveAlert(){ return haoLsBool('hao_live_alert', false); }
function haoSetLiveAlert(on){ haoLsSet('hao_live_alert', on?'1':'0'); haoRefreshSettings(); }
function haoLiveAlertRooms(){ try{ return JSON.parse(localStorage.getItem('hao_live_alert_rooms')||'{}'); }catch(e){ return {}; } }
function haoLiveAlertRoomOn(platform, roomId){ const m=haoLiveAlertRooms(); const k=platform+':'+roomId; return m[k]!==false; }
function haoSetLiveAlertRoom(key, on){ const m=haoLiveAlertRooms(); if(on) delete m[key]; else m[key]=false; try{ localStorage.setItem('hao_live_alert_rooms', JSON.stringify(m)); }catch(e){} }
function haoToggleLiveAlertRoom(btn, platform, roomId){ const cur=haoLiveAlertRoomOn(platform, roomId); haoSetLiveAlertRoom(platform+':'+roomId, !cur); if(btn){ btn.textContent=cur?'🔕':'🔔'; btn.classList.toggle('off', cur); } }
// L06: alerts poll on a timer (see haoStartLiveAlertPoll below), not
// only when #/live opens. Seen-map stores {o:0/1, s:startedAt} per
// room: alert only on offline->online, or on a NEW startedAt
// (re-broadcast). Same broadcast never alerts twice; first sight
// stays silent. A failed check keeps the previous seen state and
// never alerts. Banner is in-app only, no push.
async function haoCheckLiveAlerts(){ if(!haoLiveAlert()) return; const items=haoLiveFollowsGet(); if(!items.length) return; let seen={}; try{ seen=JSON.parse(localStorage.getItem('hao_live_alert_seen')||'{}'); }catch(e){} const next={}; const newly=[]; for(const f of items){ const key=f.platform+':'+f.roomId; try{ const st=await directLiveRoomStatus(f.platform, f.roomId); if(st.failed){ if(seen[key]!==undefined) next[key]=seen[key]; continue; } const prev=seen[key]; const wasSeen=prev!==undefined; const prevOnline=(prev===true)||(prev&&prev.o===1); const prevStart=(prev&&typeof prev==='object'&&Number(prev.s))||0; next[key]={o:st.online?1:0, s:st.online?(st.startedAt||0):0}; if(st.online&&haoLiveAlertRoomOn(f.platform, f.roomId)){ if(wasSeen&&!prevOnline) newly.push({platform:f.platform, roomId:f.roomId, uname:f.uname||f.title||'', title:st.title||''}); else if(prevOnline&&st.startedAt>0&&prevStart>0&&st.startedAt!==prevStart) newly.push({platform:f.platform, roomId:f.roomId, uname:f.uname||f.title||'', title:st.title||''}); } }catch(e){ if(seen[key]!==undefined) next[key]=seen[key]; } } try{ localStorage.setItem('hao_live_alert_seen', JSON.stringify(next)); }catch(e){} if(!newly.length) return; if(document.getElementById('liveAlertBanner')) return; const b=document.createElement('div'); b.className='live-alert-banner'; b.id='liveAlertBanner'; const first=newly[0]; const sp=document.createElement('span'); sp.style.cursor='pointer'; sp.textContent='🔔 '+t('liveAlertBanner').replace('{n}', newly.length)+'：'+newly.map(function(x){ return x.uname||x.title; }).join('、'); sp.onclick=function(){ location.hash='#/live/'+first.platform+'/'+encodeURIComponent(first.roomId); }; const xb=document.createElement('button'); xb.className='ghost-btn'; xb.textContent='✕'; xb.onclick=function(){ b.remove(); }; b.appendChild(sp); b.appendChild(xb); const box=document.getElementById('liveList'); if(box&&box.parentNode){ box.parentNode.insertBefore(b, box); return; } const app=document.getElementById('app'); if(app){ b.style.cssText+='position:fixed;top:calc(10px + env(safe-area-inset-top,0px));left:12px;right:12px;z-index:9999;margin:0;box-shadow:0 8px 24px rgba(0,0,0,.35)'; app.appendChild(b); } }
// L06: poll follow status every 90s after launch so alerts fire while
