function haoStartLiveAlertPoll(){ if(__haoAlertPollStarted) return; __haoAlertPollStarted=true; setInterval(function(){ try{ if(!document.hidden&&haoLiveAlert()&&haoLiveFollowsGet().length) haoCheckLiveAlerts(); }catch(e){} }, 90000); }
