// 20. validate a pasted music source (LX script or JSON) — doc name
function haoValidateMusicSource(text){
  const s = typeof text === 'string' ? text.trim() : '';
  if (!s) return { ok: false, error: 'empty' };
  if (window.HaoSources && typeof HaoSources.parseLxSourceScript === 'function') {
    try {
      const p = HaoSources.parseLxSourceScript(s);
      const meta = (p.def && p.def.lxMeta) || {};
      return { ok: true, kind: 'lx', name: p.def.name, version: meta.version || '', author: meta.author || '', platforms: p.platforms || [] };
    } catch (e) {
      if (/@name|inited|^\/\*!|^\/\//.test(s)) return { ok: false, error: (e && e.message) || 'invalid source' };
      try {
        const o = JSON.parse(s);
        if (!o || !o.name) throw new Error('missing @name');
        return { ok: true, kind: 'json', name: o.name, version: o.version || '', author: o.author || '', platforms: o.platforms || [] };
      } catch (e2) { return { ok: false, error: (e2 && e2.message) || 'invalid source' }; }
    }
  }
  try {
    const o = JSON.parse(s);
    if (!o || !o.name) throw new Error('missing @name');
    return { ok: true, kind: 'json', name: o.name, version: o.version || '', author: o.author || '', platforms: o.platforms || [] };
  } catch (e) { return { ok: false, error: e.message }; }
}
