// ---- settings page row builders (Pure Live-style grouped list) ----
function setRowHTML(title, sub, ctl){ return '<div class="set-row"><div class="set-row-t"><div class="set-title">' + title + '</div>' + (sub ? '<div class="set-sub">' + sub + '</div>' : '') + '</div><div class="set-ctl">' + (ctl || '') + '</div></div>'; }
function setSwitchHTML(on, call){ return '<button type="button" class="set-switch' + (on ? ' on' : '') + '" role="switch" aria-checked="' + (on ? 'true' : 'false') + '" onclick="' + call + '"><span></span></button>'; }
function setChipsHTML(opts, cur, fn){ return '<span class="set-chips">' + opts.map(function(o){ return '<button type="button" class="set-chip' + (String(cur) === String(o[0]) ? ' on' : '') + '" onclick="' + fn + '(\'' + o[0] + '\')">' + o[1] + '</button>'; }).join('') + '</span>'; }
function haoSecState(){ try{ const v=JSON.parse(localStorage.getItem('hao_set_secs')||'null'); if(v&&typeof v==='object') return v; }catch(e){} return {play:true}; }
function haoSecSave(st){ try{ localStorage.setItem('hao_set_secs', JSON.stringify(st)); }catch(e){} }
function haoSecOpen(key){ const st=haoSecState(); if(!(key in st)) return key==='play'||key.indexOf('src-')===0; return !!st[key]; }
function haoToggleSec(key){
  const body=document.querySelector('[data-sec-body="'+key+'"]');
  const head=document.querySelector('[data-sec-head="'+key+'"]');
  if(!body) return;
  const st=haoSecState(); const open=!haoSecOpen(key); st[key]=open; haoSecSave(st);
  if(head) head.classList.toggle('collapsed',!open);
  if(open){ body.classList.remove('collapsed'); body.style.maxHeight=body.scrollHeight+'px'; setTimeout(function(){ if(!body.classList.contains('collapsed')) body.style.maxHeight=''; },320); }
  else { body.style.maxHeight=body.scrollHeight+'px'; void body.offsetHeight; body.classList.add('collapsed'); body.style.maxHeight='0px'; }
}
function setGroupKey(title){
  const map={'播放':'play','直播':'live','弹幕':'dm','音乐':'music','界面':'ui','外观':'look','数据与备份':'data','关于':'about','备份管理':'backup',
    '彈幕':'dm','音樂':'music','介面':'ui','外觀':'look','數據與備份':'data','關於':'about','備份管理':'backup',
    'Playback':'play','Live':'live','Danmaku':'dm','Music':'music','Interface':'ui','Appearance':'look','Data & Backup':'data','About':'about','Backup':'backup'};
  if(map[title]) return map[title];
  if(title.indexOf('App 内备份')===0||title.indexOf('App 內備份')===0||title.indexOf('In-app backups')===0) return 'backupInApp';
  return 'sec-'+title;
}
function setGroupHTML(title, inner){ const k=setGroupKey(title); const open=haoSecOpen(k); return '<div class="set-sec set-sec-coll'+(open?'':' collapsed')+'" data-sec-head="'+esc(k)+'" onclick="haoToggleSec(\''+esc(k)+'\')"><span>'+title+'</span><span class="set-sec-chev">'+ic('chevDown')+'</span></div><div class="set-group'+(open?'':' collapsed')+'" data-sec-body="'+esc(k)+'"'+(open?'':' style="max-height:0"')+'>'+inner+'</div>'; }
