  html += setGroupHTML(t('setSecPlay'),
    setRowHTML(t('liveDefQT'), '', setChipsHTML([['', t('autoT')], ['原画', '原画'], ['蓝光8M', '蓝光8M'], ['蓝光4M', '蓝光4M'], ['超清', '超清'], ['流畅', '流畅']], haoLiveDefQ(), 'haoSetDefaultLiveQuality'))
    + setRowHTML(t('playerEngineT'), t('playerEngineSub'), setChipsHTML([['mpv', 'MPV'], ['ijk', 'IJK'], ['exo', t('playerEngineSys')]], haoPlayerEngine(), 'haoSetPlayerEngine'))
    + setRowHTML(t('cellWarnT'), t('cellWarnSub'), setSwitchHTML(haoCellWarn(), 'haoSetCellularWarn(' + (!haoCellWarn()) + ')'))
    + setRowHTML(t('defVolT'), '', '<input type="range" class="set-slider" min="0" max="100" step="1" value="' + Math.round(audio.volume * 100) + '" oninput="setVolume(this.value);document.getElementById(\'setVolVal\').textContent=this.value"> <span class="set-val" id="setVolVal">' + Math.round(audio.volume * 100) + '</span>')
    + setRowHTML(t('muteT'), '', setSwitchHTML(audio.muted, 'haoSetGlobalMute(' + (!audio.muted) + ')'))
    + setRowHTML(t('bgPlayT'), t('bgPlaySub'), setSwitchHTML(haoBgPlay(), 'haoSetBgPlay(' + (!haoBgPlay()) + ')'))
    + setRowHTML(t('keepScreenT'), t('keepScreenSub'), setSwitchHTML(haoKeepScreen(), 'haoSetKeepScreenOn(' + (!haoKeepScreen()) + ')'))
    + setRowHTML(t('sleepT'), sleepSub, setChipsHTML([['0', t('sleepOff')], ['15', '15'], ['30', '30'], ['60', '60'], ['90', '90']], String(sleepT.mins), 'haoSetSleepTimer'))
    + setRowHTML(t('hudClockT'), t('hudClockSub'), setSwitchHTML(haoHudClock(), 'haoSetHudClock(' + (!haoHudClock()) + ')'))
    + setRowHTML(t('hudSpeedT'), t('hudSpeedSub'), setSwitchHTML(haoHudSpeed(), 'haoSetHudSpeed(' + (!haoHudSpeed()) + ')'))
    + setRowHTML(t('autoPipT'), t('autoPipSub'), setSwitchHTML(haoAutoPip(), 'haoSetAutoPip(' + (!haoAutoPip()) + ')'))
    + setRowHTML(t('startupAutoPlayT'), t('startupAutoPlaySub'), setSwitchHTML(haoStartupAutoPlay(), 'haoSetStartupAutoPlay(' + (!haoStartupAutoPlay()) + ')'))
  );
  // 歌曲过渡 (Apple Music 交叉淡化, 照真机截图结构: 开关卡 + 过渡效果样式两选项)
