let listenRange='week', lastListenSongs=[];
async function renderListenReport(){ document.getElementById('app').innerHTML=`<div class="card"><p><a href="#/playlist">‹ ${t('myPlaylistT')}</a></p><h2>${ic('eq')} ${t('listenReportT')}</h2><div class="lr-range"><button type="button" data-lr-range="week" onclick="listenSetRange('week')">${t('listenWeek')}</button><button type="button" data-lr-range="month" onclick="listenSetRange('month')">${t('listenMonth')}</button><button type="button" data-lr-range="all" onclick="listenSetRange('all')">${t('listenAll')}</button></div><div id="lrBody"><p class="muted">${t('loading')}</p></div></div>`; loadListenReport(); }
function listenSetRange(r){ listenRange=r; loadListenReport(); }
function playListenSong(i){ const s=lastListenSongs[i]; if(!s) return; playTrack(s.songId,s.title,s.platform||'wy',s.cover,s.artist,0); }
async function loadListenReport(){ document.querySelectorAll('[data-lr-range]').forEach(b=>b.classList.toggle('on',b.dataset.lrRange===listenRange)); const body=document.getElementById('lrBody'); if(!body) return; const all=haoLSGet('hao_listen', []); const now=Date.now(); const span=listenRange==='week'?7*864e5:listenRange==='month'?30*864e5:0; const evs=span?all.filter(function(x){ return now-(x.at||0)<=span; }):all; if(!evs.length){ body.innerHTML=`<p class="muted">${t('listenEmpty')}</p>`; return; } let totalMs=0; const bySong={}, byArtist={}, byPlatform={}, byDay={}; evs.forEach(function(x){ totalMs+=(x.dur||0); const sk=(x.platform||'wy')+'|'+x.songId; bySong[sk]=bySong[sk]||{songId:x.songId, title:x.title||'', artist:x.artist||'', platform:x.platform||'wy', cover:x.cover||'', playCount:0}; bySong[sk].playCount++; const ak=x.artist||'—'; byArtist[ak]=(byArtist[ak]||0)+1; const pk=x.platform||'wy'; byPlatform[pk]=(byPlatform[pk]||0)+1; const day=new Date(x.at||0).toISOString().slice(0,10); byDay[day]=(byDay[day]||0)+1; }); const topSongs=Object.values(bySong).sort(function(a,b){ return b.playCount-a.playCount; }).slice(0,10); const topArtists=Object.entries(byArtist).map(function(e){ return {artist:e[0], plays:e[1]}; }).sort(function(a,b){ return b.plays-a.plays; }).slice(0,10); const topPlatforms=Object.entries(byPlatform).map(function(e){ return {platform:e[0], plays:e[1]}; }).sort(function(a,b){ return b.plays-a.plays; }); let days=[]; if(listenRange==='all'){ const byMonth={}; Object.keys(byDay).forEach(function(dd){ const m=dd.slice(0,7); byMonth[m]=(byMonth[m]||0)+byDay[dd]; }); const ms=Object.keys(byMonth).sort().slice(-12); days=ms.map(function(m){ return {day:m, plays:byMonth[m]}; }); } else { const n=listenRange==='week'?7:30; for(let i=n-1;i>=0;i--){ const dd=new Date(now-i*864e5).toISOString().slice(0,10); days.push({day:dd, plays:byDay[dd]||0}); } } const tm=Math.round(totalMs/60000); const totalTime=tm>=60?Math.floor(tm/60)+'小时'+(tm%60)+'分':tm+'分钟'; const d={ok:true, range:listenRange, totalPlays:evs.length, totalTime:totalTime, days:days, topSongs:topSongs, topArtists:topArtists, topPlatforms:topPlatforms}; lastListenSongs=d.topSongs||[]; const maxDay=Math.max(1,...(d.days||[]).map(x=>x.plays)); const maxPf=Math.max(1,...(d.topPlatforms||[]).map(x=>x.plays)); body.innerHTML=`<div class="lr-stats"><div class="lr-stat"><b>${d.totalPlays}</b><span>${t('listenTotalPlays')}</span></div><div class="lr-stat"><b>${esc(d.totalTime||'')}</b><span>${t('listenTotalTime')}</span></div></div><h3>${d.range==='all'?t('listenMonthly'):t('listenDaily')}</h3><div class="lr-bars${d.range==='all'?' lr-monthly':''}">${(d.days||[]).map(x=>`<div class="lr-bar-col" title="${esc(x.day)} · ${x.plays}${t('listenTimes')}"><div class="lr-bar" style="height:${x.plays>0?Math.max(6,Math.round(x.plays/maxDay*100)):2}%"></div><div class="lr-bar-day">${esc(d.range==='all'?x.day.slice(5):x.day.slice(3))}</div></div>`).join('')}</div><h3>${t('listenTopSongs')}</h3><div class="am-list">${lastListenSongs.map((s,i)=>`<div class="am-row"><span class="lr-rank">${i+1}</span><img class="am-art" src="${esc(s.cover||'./music-cover.svg')}" onerror="this.src='./music-cover.svg'" onclick="playListenSong(${i})" style="cursor:pointer"><div class="am-meta" onclick="playListenSong(${i})" style="cursor:pointer"><div class="am-title">${esc(s.title)}</div><div class="am-sub">${esc(s.artist)} · ${pfName(s.platform)}</div></div><span class="lr-count">${s.playCount}${t('listenTimes')}</span></div>`).join('')}</div>${(d.topArtists||[]).length?`<h3>${t('listenTopArtists')}</h3><div class="am-list">${d.topArtists.map((a,i)=>`<div class="am-row"><span class="lr-rank">${i+1}</span><div class="am-meta"><div class="am-title">${esc(a.artist)}</div><div class="am-sub">${a.plays}${t('listenTimes')}</div></div></div>`).join('')}</div>`:''}${(d.topPlatforms||[]).length?`<h3>${t('listenPlatforms')}</h3>${d.topPlatforms.map(p=>`<div class="lr-pf"><span>${pfName(p.platform)}</span><div class="lr-pf-track"><div class="lr-pf-fill" style="width:${Math.round(p.plays/maxPf*100)}%"></div></div><b>${p.plays}</b></div>`).join('')}`:''}`; }
let myPlView='hub';
