function retryArtistDetail(){ if(lastArtistReq) openArtistById(lastArtistReq.platform,lastArtistReq.id,lastArtistReq.name); }
async function renderVideoPage(){ document.getElementById('app').innerHTML=`<div class="vod-home"><div class="vod-top"><button class="vod-search-pill" onclick="location.hash='#/video/search'">${ic('search')}<span>${t('searchVideoPh')}</span></button><button class="vod-heart" onclick="location.hash='#/video/favorites'" title="${t('favT')}">${ic('heart')}</button></div><div id="videoRes"></div><div id="vodHomeBody">${vodHomeSkelHTML()}</div></div>`; loadVideoHome().catch(function(err){ const b=document.getElementById('vodHomeBody'); if(b) b.innerHTML=loadErrHTML('loadVideoHome()','videoSrcDownT'); }); }
let videoSearchSeq=0;
async function searchVideo(){ const q=document.getElementById('videoQ').value.trim(); if(!q) return; vodSearchHistSave(q); const el=document.getElementById('videoRes'); if(!el) return; const mySeq=++videoSearchSeq; el.innerHTML=skelPosterGridHTML(6); let r=null; if(nativeFetchAvailable()){ try{ r=await Promise.race([directVideoSearch(q),new Promise(res=>setTimeout(()=>res({__timeout:true}),55000))]); if(r&&r.__timeout) r=null; }catch(e){ r=null; } } if(mySeq!==videoSearchSeq||!document.getElementById('videoRes')) return; if(!r||r.__timeout||!r.ok){ el.innerHTML=loadErrHTML('searchVideo()','videoSrcDownT'); return; } lastVideo=r.results||[]; el.innerHTML=lastVideo.length?`<div class="vod-grid">${lastVideo.map((x,i)=>vodPosterCard(x,i<6)).join('')}</div>`:`<p class="vod-loading">${t('noVideo')}</p>`; armVodPosterFallback(); }
let videoSearchPageSeq=0, videoHotCache=null;
