function vodSearchHistSave(q){ if(!q) return; let h=vodSearchHistGet().filter(x=>x!==q); h.unshift(q); h=h.slice(0,8); try{ localStorage.setItem('vodSearchHist',JSON.stringify(h)); }catch(e){} }
