async function renderVideoSearchPage(){ const qm=(location.hash.split('?')[1]||'').match(/(?:^|&)q=([^&]*)/); const initQ=qm?decodeURIComponent(qm[1]):''; document.getElementById('app').innerHTML=`<div class="vod-home"><div class="vod-search"><input id="videoSearchQ" placeholder="${t('searchVideoPh')}" value="${esc(initQ)}" onkeydown="if(event.key==='Enter')searchVideoPage()"><button type="button" onclick="searchVideoPage()">${t('searchBtn')}</button></div><div id="videoSearchSide"></div><div id="videoSearchRes"></div></div>`; renderVideoSearchChips(); if(initQ) searchVideoPage(); }
function renderVideoSearchChips(){ const side=document.getElementById('videoSearchSide'); if(!side) return; const hist=vodSearchHistGet(); let h=''; if(hist.length){ h+=`<div class="vod-search-sec"><div class="vod-search-sec-head"><span>${t('videoHistT')}</span><span class="vod-sec-more" onclick="vodSearchHistClear()">${t('videoClearHistT')}</span></div><div class="vod-chips">${hist.map(q=>`<button class="vod-chip" data-q="${esc(q)}" onclick="videoSearchFill(this.getAttribute('data-q'))">${esc(q)}</button>`).join('')}</div></div>`; } h+=`<div class="vod-search-sec"><div class="vod-search-sec-head"><span>${t('videoHotT')}</span></div><div class="vod-chips" id="videoHotChips"><span class="vod-loading">${t('loading')}</span></div></div>`; side.innerHTML=h; loadVideoHotChips(); }
async function loadVideoHotChips(){ const box=document.getElementById('videoHotChips'); if(!box) return; let names=videoHotCache||[]; if(!names.length){ try{ let d=null; if(nativeFetchAvailable()){ try{ const dd=await directVideoDaily(); if(dd&&dd.items&&dd.items.length) d=dd; }catch(e){} } names=((d&&d.items)||[]).map(x=>x.name).filter(Boolean); if(names.length) videoHotCache=names; }catch(e){} } if(!names.length) names=['繁花','庆余年','哪吒','流浪地球','甄嬛传','狂飙','长津湖','三体']; if(!document.getElementById('videoHotChips')) return; box.innerHTML=names.slice(0,8).map(n=>`<button class="vod-chip" data-q="${esc(n)}" onclick="videoSearchFill(this.getAttribute('data-q'))">${esc(n)}</button>`).join(''); }
async function searchVideoPage(){ const inp=document.getElementById('videoSearchQ'); const q=inp?inp.value.trim():''; const el=document.getElementById('videoSearchRes'); if(!el) return; if(!q){ el.innerHTML=''; return; } vodSearchHistSave(q); renderVideoSearchChips(); const mySeq=++videoSearchPageSeq; el.innerHTML=skelPosterGridHTML(6); let r=null; if(nativeFetchAvailable()){ try{ r=await Promise.race([directVideoSearch(q),new Promise(res=>setTimeout(()=>res({__timeout:true}),55000))]); if(r&&r.__timeout) r=null; }catch(e){ r=null; } } if(mySeq!==videoSearchPageSeq||!document.getElementById('videoSearchRes')) return; if(!r||r.__timeout||!r.ok){ el.innerHTML=loadErrHTML('searchVideoPage()','videoSrcDownT'); return; } lastVideo=r.results||[]; if(!lastVideo.length){ el.innerHTML=`<div class="empty"><div class="empty-ico">🔍</div><div class="empty-title">${t('videoNoResT')}：${esc(q)}</div><div class="empty-text" style="text-align:left;display:inline-block"><div>· ${t('videoNoResTip1')}</div><div>· ${t('videoNoResTip2')}</div><div>· ${t('videoNoResTip3')}</div></div><p style="margin-top:16px"><button type="button" onclick="location.hash='#/video'">${t('videoBrowseCatsT')}</button></p></div>`; return; } el.innerHTML=`<div class="vod-grid">${lastVideo.map((x,i)=>vodPosterCard(x,i<6)).join('')}</div>`; armVodPosterFallback(); }
