async function clearVideoHistory(){ if(!(await showConfirm({title:t('confirmClearVideoHistory')}))) return; haoVideoHistSave([]); loadVideoHistory(); }
function vodHistDel(e, key){ if(e&&e.stopPropagation) e.stopPropagation(); const k=String(key); haoVideoHistSave(haoVideoHistGet().filter(function(x){ return String(x.source)+'|'+String(x.vodId)!==k; })); loadVideoHistory(); }
function vodDailyHTML(daily){ if(!daily||!daily.length) return ''; return `<div class="vod-sec"><div class="vod-sec-head"><span>${t('dailyVideoT')}</span></div><div class="vod-poster-row">`+daily.map(x=>vodPosterCard({source:x.source,vodId:x.vodId,name:x.name,pic:x.pic,picAlt:x.picAlt,year:x.year,score:x.score||'',total:x.total||'',type:x.type})).join('')+`</div></div>`; }
