async function openVideoType(name){ vodTypeName=name; vodTypePage=1; vodTypeArea='all'; vodTypeYear='all'; vodTypeSort='time'; document.getElementById('app').innerHTML=`<div class="vod-home"><div class="vod-top"><button class="vod-back" onclick="renderVideoPage()">‹ ${t('back')}</button><div class="vod-top-title">${esc(name)}</div><span style="width:40px"></span></div><div id="vodFilterBar">${vodFilterBarHTML()}</div><div id="vodTypeBody">${skelPosterGridHTML(6)}</div></div>`; loadVideoType(); }
function vodFilterBarHTML(){ const chip=function(g,v,lb,cur){ return `<button class="vod-chip${cur===v?' on':''}" data-g="${g}" data-v="${v}" onclick="vodFilterSet('${g}','${v}')">${lb}</button>`; }; const areas=[['all',t('filterAll')],['大陆','大陆'],['香港','香港'],['台湾','台湾'],['美国','美国'],['韩国','韩国'],['日本','日本'],['英国','英国'],['other',t('filterOther')]]; const years=[['all',t('filterAll')],['2026','2026'],['2025','2025'],['2024','2024'],['2023','2023'],['2022','2022'],['earlier',t('filterEarlier')]]; const sorts=[['time',t('sortTime')],['hits',t('sortHits')],['score',t('sortScore')]]; return `<div class="vod-filter-bar"><div class="vod-filter-group"><span class="vod-filter-label">${t('filterAreaT')}</span>${areas.map(a=>chip('area',a[0],a[1],vodTypeArea)).join('')}</div><div class="vod-filter-group"><span class="vod-filter-label">${t('filterYearT')}</span>${years.map(a=>chip('year',a[0],a[1],vodTypeYear)).join('')}</div><div class="vod-filter-group"><span class="vod-filter-label">${t('filterSortT')}</span>${sorts.map(a=>chip('sort',a[0],a[1],vodTypeSort)).join('')}</div></div>`; }
function vodFilterSet(g,v){ if(g==='area') vodTypeArea=v; else if(g==='year') vodTypeYear=v; else vodTypeSort=v; vodTypePage=1; const bar=document.getElementById('vodFilterBar'); if(bar){ bar.innerHTML=vodFilterBarHTML(); vodFilterScrollSel(g,v); } loadVideoType(); }
function vodFilterScrollSel(g,v){ try{ const bar=document.getElementById('vodFilterBar'); if(!bar) return; const el=bar.querySelector('.vod-chip[data-g="'+g+'"][data-v="'+v+'"]'); if(el) el.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'}); }catch(e){} }
let vodTypeSeq=0;
let vodTypeItems=[], vodTypeShown=0; const VOD_TYPE_CHUNK=20;
async function loadVideoType(){ const mySeq=++vodTypeSeq; const body=document.getElementById('vodTypeBody'); if(!body) return; let r=null; try{ if(nativeFetchAvailable()){ try{ const dd=await Promise.race([directVideoByType(vodTypeName,vodTypePage,vodTypeArea,vodTypeYear,vodTypeSort),new Promise(res=>setTimeout(()=>res({__timeout:true}),25000))]); if(dd&&!dd.__timeout&&dd.ok) r=dd; }catch(e){} } }catch{} if(mySeq!==vodTypeSeq) return; if(!document.getElementById('vodTypeBody')) return; if(!r||r.__timeout||!r.ok){ body.innerHTML=loadErrHTML('loadVideoType()',(r&&r.error==='type not found')?'loadFailT':'videoSrcDownT'); return; } if(!(r.items||[]).length){ body.innerHTML=`<p class="vod-loading">${t('noVideo')}</p>`; return; } const pages=Math.max(1,r.pagecount||1); vodTypeItems=r.items||[]; vodTypeShown=0; body.innerHTML=`<div class="vod-grid" id="vodTypeGrid"></div><div id="vodTypeMoreWrap" style="text-align:center;margin-top:14px"></div><div class="vod-pager"><button class="ghost-btn" onclick="vodTypePageSet(-1)" ${vodTypePage<=1?'disabled':''}>${t('prevPage')}</button><span class="vod-loading">${vodTypePage}/${pages}</span><button class="ghost-btn" onclick="vodTypePageSet(1)" ${vodTypePage>=pages?'disabled':''}>${t('nextPage')}</button></div>`; vodTypeAppendChunk(); }
