// Long-press 2x on the video area (web player only; the App uses the native
// player, which has its own long-press). Hold ~500ms without moving to get
// a temporary 2x; release restores the chosen speed. A swipe (>10px) cancels
// the timer so it never fights swipe-seek; buttons / overlay / settings are
// excluded, so tapping a control never triggers it.
let vodLp2Timer=null, vodLp2Active=false, vodLp2Start=null;
function initVodSpeedLongPress(){
  const w=document.getElementById('videoWrap'); if(!w) return;
  const v=document.getElementById('videoPlayer'); if(!v) return;
  const ind=document.getElementById('vodSpeedInd');
  function cancelLp2(){ if(vodLp2Timer){ clearTimeout(vodLp2Timer); vodLp2Timer=null; } if(vodLp2Active){ vodLp2Active=false; try{ v.playbackRate=vodSpeed; }catch(e){} if(ind) ind.style.display='none'; } }
  w.addEventListener('pointerdown',function(e){
    if(e.target.closest('button,input,select,a,.dm-settings,.fs-ctl,.video-overlay,.dm-layer')) return;
    if(!v.currentSrc) return;
    vodLp2Start={x:e.clientX,y:e.clientY};
    vodLp2Timer=setTimeout(function(){
      vodLp2Timer=null; vodLp2Active=true;
      try{ v.playbackRate=2; }catch(e){}
      if(ind) ind.style.display='block';
    },500);
  });
  w.addEventListener('pointermove',function(e){
    if(vodLp2Start&&Math.hypot(e.clientX-vodLp2Start.x,e.clientY-vodLp2Start.y)>10){ if(vodLp2Timer){ clearTimeout(vodLp2Timer); vodLp2Timer=null; } }
  });
  w.addEventListener('pointerup',function(){ vodLp2Start=null; cancelLp2(); });
  w.addEventListener('pointercancel',function(){ vodLp2Start=null; cancelLp2(); });
  w.addEventListener('contextmenu',function(e){ if(vodLp2Active) e.preventDefault(); });
}
