    const parents = items.map(function (c) { return { id: c.id, name: c.name }; });
    const games = [];
    items.forEach(function (c) { (c.children || []).forEach(function (s) { games.push({ id: s.id, name: s.name, pic: s.pic || '', parent: c.id, parentName: c.name }); }); });
    return { parents: parents, games: games };
