    const parents = [];
    const seen = {};
    items.forEach(function (g) { const bt = g.bt || 0; if (!seen[bt]) { seen[bt] = true; parents.push({ id: String(bt), name: btName[bt] || '其他' }); } });
    const order = { '1': 0, '2': 1, '3': 2, '8': 3 };
    parents.sort(function (a, b) { return (order[a.id] === undefined ? 9 : order[a.id]) - (order[b.id] === undefined ? 9 : order[b.id]); });
    const games = items.map(function (g) { return { id: g.id, name: g.name, pic: g.pic || '', parent: String(g.bt || 0), parentName: btName[g.bt] || '其他' }; });
