  let i=(liveSearchItems||[]).findIndex(x=>x.platform===p&&String(x.roomId)===String(r)); if(i>=0) return {list:liveSearchItems, idx:i};
  i=(liveFollowItems||[]).findIndex(x=>x.platform===p&&String(x.roomId)===String(r)); if(i>=0) return {list:liveFollowItems, idx:i};
  i=(liveRooms||[]).findIndex(x=>String(x.roomId)===String(r)); if(i>=0) return {list:liveRooms, idx:i};
