async function loadComments(songId, pf, title, artist){
  const el = document.getElementById('commentsBody');
  if(!el) return;
  cmtOffset = 0; cmtHasMore = false; cmtLoading = false;
  cmtSongId = songId; cmtPf = pf; cmtTitle = title || ''; cmtArtist = artist || '';
  el.innerHTML = `<p class="muted">${t('loadingComments')}</p>`;
  try{
    let r = null;
    if (nativeFetchAvailable()) { try { r = await directComments(songId, pf, title || '', artist || '', 0); if (r && r.ok === false) r = null; } catch (e) { r = null; } }
    if(!r || r.ok === false) throw new Error((r && r.error) || 'comments fail');
    const hot = r.hot || [], latest = r.latest || r.comments || [];
    cmtHasMore = !!r.hasMore;
    cmtOffset = latest.length;
    let html = '';
    if(hot.length) html += `<div class="cmt-sec-title hot">⭐ ${t('hotCommentsT')}</div>` + hot.map(c => cmtRow(c, true)).join('');
    if(latest.length) html += `<div class="cmt-sec-title">${t('latestCommentsT')}</div><div id="cmtLatest">` + latest.map(c => cmtRow(c, false)).join('') + `</div>`;
    if(!hot.length && !latest.length) html = `<p class="muted">${t('noComments')}</p>`;
    if(cmtHasMore) html += `<button id="cmtMoreBtn" class="cmt-more-btn" onclick="loadMoreComments()">${t('loadMoreT')}</button>`;
    el.innerHTML = html;
  }catch{
    el.innerHTML = `<p class="muted">${t('commentsFailT')}</p><button onclick="loadComments(curSongId,curPf,curTrack,curArtist)">${t('retryT')}</button>`;
  }
}
async function loadMoreComments(){
  if(cmtLoading || !cmtHasMore) return;
  if(curSongId !== cmtSongId || curPf !== cmtPf) return;
  cmtLoading = true;
  const btn = document.getElementById('cmtMoreBtn');
  if(btn) btn.textContent = t('loadingComments');
  try{
    let r = null;
    if (nativeFetchAvailable()) { try { r = await directComments(cmtSongId, cmtPf, cmtTitle, cmtArtist, cmtOffset); if (r && r.ok === false) r = null; } catch (e) { r = null; } }
    if(!r || r.ok === false) throw new Error('more fail');
    const list = r.latest || [];
    cmtHasMore = !!r.hasMore;
    cmtOffset += list.length;
    const box = document.getElementById('cmtLatest');
    if(box){
      const have = new Set([...box.querySelectorAll('.cmt')].map(row => { const b = row.querySelector('b'); const tx = row.querySelector('.cmt-text'); return (b ? b.textContent : '') + '|' + (tx ? tx.textContent : '').slice(0, 60); }));
      const fresh = list.filter(c => !have.has((c.nick || '') + '|' + (c.content || '').slice(0, 60)));
      box.insertAdjacentHTML('beforeend', fresh.map(c => cmtRow(c, false)).join(''));
    }
    if(btn){
      if(cmtHasMore) btn.textContent = t('loadMoreT');
      else btn.outerHTML = `<p class="muted" style="text-align:center">${t('allLoadedT')}</p>`;
    }
  }catch{
    if(btn) btn.textContent = t('retryT');
  }
  cmtLoading = false;
}
