// Crossfade: two <audio> elements ping-pong (xfAudio is the spare); handlers
// only act for the element currently assigned to `audio` (the spare's events
// are ignored), and `ended` never fires nextTrack mid-fade.
function bindAudioEl(el){
  el.addEventListener('loadedmetadata',(e)=>{ if(e.currentTarget!==audio) return; if(qualityResume){ const qr=qualityResume; qualityResume=null; if(qr.pos>0&&audio.duration&&qr.pos<audio.duration-2){ try{ audio.currentTime=qr.pos; }catch(e){} } } if(restorePos){ const rp=restorePos; if(rp>0&&audio.duration&&rp<audio.duration-2){ try{ audio.currentTime=rp; }catch(e){} } } });
  el.addEventListener('canplay',(e)=>{ if(e.currentTarget!==audio) return; if(restorePos){ const rp=restorePos; restorePos=0; if(rp>0&&audio.duration&&rp<audio.duration-2&&Math.abs(audio.currentTime-rp)>2){ try{ audio.currentTime=rp; }catch(e){} } } });
  el.addEventListener('ended',(e)=>{ if(e.currentTarget!==audio) return; if(xfActive) return; if(playerPlaylist.length&&curTrackIdx>=0){ nextTrack(true);} else { playing=false; wantPlaying=false; clearWebAutoResume(); updateVinyl(); postMusicLyrics('stop'); postNowPlaying();}});
  el.addEventListener('ended',(e)=>{ if(e.currentTarget!==audio) return; clearLastSong(); });
  el.addEventListener('error',(e)=>{ if(e.currentTarget!==audio) return; qualityResume=null; if(!audio.src||audio.src===errFor) return; errFor=audio.src; tryNextCandidate();});
  el.addEventListener('stalled',(e)=>{ if(e.currentTarget!==audio) return; if(wantPlaying&&audio.paused){ audio.play().catch(()=>{}); }});
  el.addEventListener('suspend',(e)=>{ if(e.currentTarget!==audio) return; if(wantPlaying&&audio.paused&&audio.readyState>=2){ audio.play().catch(()=>{}); }});
  el.addEventListener('timeupdate',(e)=>{ if(e.currentTarget!==audio) return; tickPlayer(); syncLyrics(); });
  el.addEventListener('seeked',(e)=>{ if(e.currentTarget!==audio) return; syncLyrics(); postMusicLyrics('seek'); });
  el.addEventListener('play',(e)=>{ if(e.currentTarget!==audio) return; playing=true; playFailStreak=0; clearWebAutoResume(); updateVinyl(); updateMediaSession(); postMusicLyrics('resume'); postNowPlaying(); tickPlayer(); });
  el.addEventListener('pause',(e)=>{ if(e.currentTarget!==audio) return; playing=false; updateVinyl(); updateMediaSession(); postMusicLyrics('pause'); postNowPlaying(); if(wantPlaying) scheduleWebAutoResume(); });
}
// ===== Last song: only the song currently playing is remembered =====
// One record (not a per-song map): the song in the player + its position.
// On reopen, that same song is restored into the player, ready to continue.
// Songs that never played have no saved progress.
let lastSongRestored=false, restorePos=0;
function saveLastSong(){
  if(!haoSavePlayTime()) return;
  if(!curSongId||!curTrack) return;
  if(!audio.duration||!isFinite(audio.duration)) return;
  const pos=audio.currentTime||0;
  if(pos<5||pos>audio.duration-10) return;
  try{ localStorage.setItem('haoLastSong', JSON.stringify({songId:curSongId, platform:curPf||'wy', title:curTrack, artist:curArtist||'', cover:curCover||'', pos:Math.floor(pos), dur:Math.floor(audio.duration), at:Date.now()})); }catch(e){}
}
function clearLastSong(){ try{ localStorage.removeItem('haoLastSong'); }catch(e){} }
async function restoreLastSong(){
  if(lastSongRestored) return; lastSongRestored=true;
  let s=null; try{ s=JSON.parse(localStorage.getItem('haoLastSong')||'null'); }catch(e){}
  if(!s||!s.songId||!s.pos||s.pos<5) return;
  if(s.dur&&s.pos>s.dur-10) return;
  if(!playerPlaylist.length && !queueCleared){ try{ await loadPlayerPlaylist(); }catch(e){} }
  const idx=playerPlaylist.findIndex(t=>String(t.songId)===String(s.songId)&&(t.platform||'wy')===(s.platform||'wy'));
  if(idx>=0){ curTrackIdx=idx; } else {
    playerPlaylist.unshift({songId:s.songId, title:s.title, artist:s.artist||'', platform:s.platform||'wy', cover:s.cover||'', vipOnly:0, dur:s.dur||0});
    curTrackIdx=0;
  }
  curSongId=s.songId; curPf=s.platform||'wy'; curTrack=s.title; curArtist=s.artist||''; curCover=s.cover||'';
  updateVinyl(); updatePlayer();
  try{
    const r=await getPlayUrl(s.songId, s.platform||'wy', curQuality, s.title, s.cover||'');
    if(!r||!r.url) return;
    curCandidates=(r.candidates&&r.candidates.length?r.candidates:[r.url]); curCandIdx=0; errFor='';
    restorePos=s.pos;
    audio.src=curCandidates[0];
    if(haoStartupAutoPlay()){ if(tryNativeMusicPlay(curCandidates[0], restorePos)){ playing=true; updateVinyl(); updatePlayer(); } else { audio.play().catch(()=>{}); } }
    // No autoplay by default: iOS needs a user gesture. The song sits in the player, ready to continue.
  }catch(e){}
}
