window.__nativeMusicStarted=function(){ nativeMusicOn=true; if(__nativeFallbackTimer){ clearTimeout(__nativeFallbackTimer); __nativeFallbackTimer=null; } playing=true; wantPlaying=true; updateVinyl(); updatePlayer(); postNowPlaying(); };
window.__nativeMusicTick=function(pos,dur){ nativePos=Number(pos)||0; nativeDur=Number(dur)||0; tickPlayer(); syncLyrics(); };
window.__nativeMusicEnded=function(){ nativeMusicOn=false; if(playerPlaylist.length&&curTrackIdx>=0){ nextTrack(true); } else { playing=false; wantPlaying=false; clearWebAutoResume(); updateVinyl(); postMusicLyrics('stop'); postNowPlaying(); } };
window.__nativeMusicState=function(p,user){ playing=!!p; if(user!==false) wantPlaying=!!p; updateVinyl(); updatePlayer(); postNowPlaying(); };
window.__nativeMusicError=function(){ nativeMusicOn=false; if(__nativeFallbackTimer){ clearTimeout(__nativeFallbackTimer); __nativeFallbackTimer=null; } if(curTrack&&curCandIdx<curCandidates.length-1){ curCandIdx++; if(tryNativeMusicPlay(curCandidates[curCandIdx],nativePos)) return; } if(curTrack&&curCandidates.length){ audio.src=curCandidates[curCandIdx]||curCandidates[0]; audio.play().catch(function(){}); } };

// Web-side auto-resume (fix 2026-11-15, v11.7): the system can pause <audio> when the app
// returns from the background, AFTER Swift's one-shot resume already verified "playing"
// and cleared its flag — so the song stayed stopped even though the user never paused.
// `wantPlaying` is the user's intent (set ONLY by user actions, never by a pause event);
// when a pause fires while the user still wants music, it is a system pause, so keep
// retrying play() every second until it takes (audio session re-activated, WebContent
// awake) or the user pauses. No timing window, no single attempt — the retry stops only
// on real playback or a real user pause.
var __webResumeTimer=null, __webResumeTries=0;
function clearWebAutoResume(){ if(__webResumeTimer){ clearTimeout(__webResumeTimer); __webResumeTimer=null; } __webResumeTries=0; }
function scheduleWebAutoResume(){
  if(!wantPlaying||!curTrack||__webResumeTimer) return;
  __webResumeTries=0;
  const tick=function(){
    __webResumeTimer=null;
    if(!wantPlaying||!curTrack||!audio.paused) return;
    if(__webResumeTries>=30) return;
    __webResumeTries++;
    audio.play().catch(function(){});
    if(audio.paused) __webResumeTimer=setTimeout(tick,50);
  };
  // First attempt runs IMMEDIATELY (0ms), not after 500ms: the system
  // pause on foreground entry is brief, and a 500ms wait is exactly the
  // audible "pause" the user hears. Calling play() synchronously inside
  // the pause handler restarts output within tens of ms (the stream is
  // already buffered), so the gap is imperceptible. If play() is rejected
  // (WebContent not awake yet) the retry loop catches it every 50ms —
  // the old 250ms interval was itself the audible gap: one rejected
  // first attempt meant 250ms of silence. 50ms is near-imperceptible,
  // and the visibilitychange resume below catches the exact moment the
  // page is visible again, sooner than any fixed timer.
  tick();
}
// Foreground-entry resume: when the page becomes visible again (the app
// was just foregrounded) and the user still wants music but <audio> is
// paused, retry play() immediately. The document turning visible is the
// earliest signal the WebContent/media pipeline is awake again — the
// system pause fires while the page is still transitioning, so the
// synchronous play() in the pause handler can be rejected; this catches
// the first moment it can succeed. User pauses are unaffected
// (wantPlaying is false then, so nothing runs).
document.addEventListener('visibilitychange',()=>{
  if(!document.hidden&&wantPlaying&&curTrack&&audio.paused){
    audio.play().catch(function(){});
    if(audio.paused) scheduleWebAutoResume();
  }
});
