render(); // 主页直接显示，不等网络
load(); // 后台再去拉最新数据，到了自动刷新页面

/* perf+visual batch (2026-11-15): first-screen images load eagerly.
   The app renders poster/cover <img loading="lazy"> everywhere, including the
   first screen, so the first viewport stays blank until the browser gets
   around to them. This observer upgrades the first 9 lazy images in each
   render batch to eager + fetchpriority high. Self-contained; touches no
   other function.
   (dorami r2) Community post images are excluded: the list marks only the
   first post eager and the rest lazy on purpose, and this observer would
   otherwise flip those back to eager on every render. */
(function(){
  try{
    var appEl = document.getElementById('app');
    if(!appEl || !('MutationObserver' in window)) return;
    function upgrade(){
      var imgs = appEl.querySelectorAll('img[loading="lazy"]');
      var n = 0;
      for(var i = 0; i < imgs.length && n < 9; i++){
        imgs[i].setAttribute('loading','eager');
        imgs[i].setAttribute('fetchpriority','high');
        n++;
      }
    }
    var mo = new MutationObserver(function(){ upgrade(); });
    mo.observe(appEl, { childList:true, subtree:true });
    upgrade();
  }catch(e){}
})();

// ===== Music player rebuild (LX-inspired, HAo style) =====
